@Composable fun CustomEditor(ui:NativeUi,type:String,data:JSONObject){val s=ui.store;val custom=type=="custom";val date=data.s("date",today());val source=if(custom)s.day(date) else JSONObject();val list=remember{mutableStateListOf<JSONObject>().apply{addAll(source.a("items").objects().map{it.copyJson()})}};val tasks=remember{mutableStateListOf<String>().apply{addAll(source.a("tasks").objects().map{it.s("text")})}};var title by remember{mutableStateOf(source.s("title",if(custom)"Mi misión" else "Mi rutina"))};var query by remember{mutableStateOf("")};var newTask by remember{mutableStateOf("")};var category by remember{mutableStateOf("strength")}
 Heading(if(custom)"Personalizar misión" else "Crear mi rutina",size=33)
 if(custom&&(date<today()||s.activeLog(s.logs.optJSONObject(date)))){HNotice("Este día ya tiene actividad o pertenece al pasado. Sus registros se conservan.");return}
 HInput(title,{title=it},"Nombre");if(!custom)HSelect("Tipo",category,listOf("strength" to "Fuerza","cardio" to "Cardio","recovery" to "Movilidad","mixed" to "Mixta")){category=it}
 for((i,x)in list.withIndex()){val e=s.catalog.byId[x.s("id")]?:continue;HPanel(padding=15){Heading(e.name,size=26);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){HSelect("Series",x.i("sets").toString(),(1..4).map{it.toString() to it.toString()},Modifier.weight(1f)){v->val changed=x.copyJson().put("sets",v.toInt());list[i]=s.planner.cap(e,s.adjusted(),s.rules.groupDose(e,s.adjusted(),if(e.type=="cardio")"cardio" else if(e.type=="mobility")"recovery" else "strength",changed),s.logs)};HInput(x.i("target").toString(),{v->v.toIntOrNull()?.takeIf{it in 1..if(e.unit=="sec")300 else 50}?.let{n->val changed=x.copyJson().put("target",n);list[i]=s.planner.cap(e,s.adjusted(),s.rules.groupDose(e,s.adjusted(),if(e.type=="cardio")"cardio" else if(e.type=="mobility")"recovery" else "strength",changed),s.logs)}},if(e.unit=="sec")"Segundos" else "Repeticiones",Modifier.weight(1f),number=true)};Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){HButton("↑",enabled=i>0){val x2=list.removeAt(i);list.add(i-1,x2)};HButton("↓",enabled=i<list.lastIndex){val x2=list.removeAt(i);list.add(i+1,x2)};HButton("Quitar"){list.removeAt(i)}}}}
 HInput(query,{query=it},"Buscar ejercicio para añadir");if(query.isNotBlank()){val candidates=s.catalog.exercises.filter{normalize(it.name).contains(normalize(query))&&list.none{x->x.s("id")==it.id}&&s.rules.compatible(it,s.adjusted())}.take(16);if(candidates.isEmpty())HNotice("No hay ejercicios compatibles con esa búsqueda.");for(e in candidates)HButton("+ ${e.name}"){val kind=if(e.type=="cardio")"cardio" else if(e.type=="mobility")"recovery" else "strength";list+=s.planner.cap(e,s.adjusted(),s.rules.groupDose(e,s.adjusted(),kind,s.planner.libraryDose(e,s.adjusted(),kind)),s.logs);query=""}}
 if(custom){Heading("Objetivos personales del día",size=27);for((i,t)in tasks.withIndex())Row(verticalAlignment=Alignment.CenterVertically){HText(t,Modifier.weight(1f),size=16);HButton("×"){tasks.removeAt(i)}};HInput(newTask,{newTask=it},"Nuevo objetivo");HButton("+ Añadir objetivo"){if(newTask.isNotBlank()){tasks+=newTask;newTask=""}}}
 HButton("Guardar",Modifier.fillMaxWidth(),primary=true){ui.attempt{require(title.isNotBlank());if(custom)s.customize(date,list.toList(),tasks.toList(),title) else{require(list.isNotEmpty()){"Añade al menos un ejercicio"};val r=obj("id" to "custom-"+System.currentTimeMillis(),"name" to title.take(160),"category" to if(category=="mixed")"Mixta" else kindLabel(category),"level" to level(s.profile?:JSONObject()),"items" to arr(list.toList()),"description" to "Rutina personal","custom" to true);r.put("minutes",s.planner.minutes(r,s.adjusted()));val rs=s.state.a("customRoutines");rs.put(r);s.state.put("customRoutines",rs);s.save()};ui.back();ui.message(if(custom)"Misión guardada" else "Rutina guardada en tu biblioteca")}}
}
@Composable fun Academy(ui:NativeUi){val e=ui.store.catalog.editorial;Eyebrow("ACADEMIA DEL CAZADOR");Heading("Aprende a entrenar.");HText("Guías y demostraciones disponibles sin conexión. Los enlaces de consulta se abren con Internet.",color=LocalHunter.current.muted);HButton("Biblioteca de anatomía y motricidad"){ui.open("body")};for((i,g)in e.a("guides").objects().withIndex())HPanel(onClick={ui.open("guide",obj("index" to i))},padding=17){Eyebrow(g.s("group"));Heading(g.s("title"),size=26)};Heading("Galería de movimientos",size=31);var query by remember{mutableStateOf("")};HInput(query,{query=it},"Buscar demostración");val all=ui.store.catalog.exercises.filter{it.raw.s("variant")=="base"&&normalize(it.name).contains(normalize(query))};HText("${all.size} movimientos",size=15);for(pair in all.take(if(query.isBlank())64 else 40).chunked(2))Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){for(x in pair)HPanel(Modifier.weight(1f),onClick={ui.open("exercise",obj("id" to x.id))},padding=12){HText("◉ 2D",color=LocalHunter.current.accent,size=28);HText(x.name,size=16)};if(pair.size==1)Spacer(Modifier.weight(1f))};HText("Recursos visuales originales; no se redistribuyen vídeos de terceros.",size=14,color=LocalHunter.current.muted)}
@Composable fun GuideDetail(ui:NativeUi,index:Int){val editorial=ui.store.catalog.editorial;val g=editorial.a("guides").optJSONObject(index)?:return;Eyebrow(g.s("group"));Heading(g.s("title"),size=33);HText(g.s("body"));for(t in g.a("points").strings())HText("• $t");for(key in g.a("sources").strings()){val src=editorial.o("sources").o(key);HButton(src.s("name",key)){ui.openUrl(src.s("url"))}}}
@Composable fun BodyLibrary(ui:NativeUi){val editorial=ui.store.catalog.editorial;var query by remember{mutableStateOf("")};Heading("Anatomía y motricidad",size=33);HInput(query,{query=it},"Buscar concepto");for(x in editorial.a("body").objects().filter{query.isBlank()||normalize(it.toString()).contains(normalize(query))})HPanel(padding=17){Eyebrow(x.s("category"));Heading(x.s("title"),size=26);HText(x.s("body"),size=17);val src=editorial.o("bodySources").o(x.s("source"));if(src.s("url").isNotBlank())HButton(src.s("name")){ui.openUrl(src.s("url"))}}}
