@Composable fun CreatorDetail(ui:NativeUi,key:String){val s=ui.store;val channel=s.state.o("creatorData").a("channels").objects().firstOrNull{it.s("key")==key}?:s.catalog.editorial.a("channels").objects().firstOrNull{it.s("key")==key}?:return;Heading(channel.s("name"),size=34);HButton("Abrir canal original ↗",Modifier.fillMaxWidth(),primary=true){ui.openUrl(channel.s("url"))};HButton("Actualizar publicaciones"){ui.open("creator-refresh")};HNotice("Los títulos y enlaces de referencia no se convierten en rutinas ni cantidades de entrenamiento.");var query by remember{mutableStateOf("")};HInput(query,{query=it},"Buscar publicación");val videos=channel.a("videos").objects().filter{query.isBlank()||normalize(it.s("title")).contains(normalize(query))};HText("${videos.size} publicaciones guardadas",size=16);for(video in videos)HPanel(onClick={ui.openUrl(video.s("url"))},padding=16){HText(video.s("title"),bold=true);HText(video.s("published").take(10)+"  ↗",size=15,color=LocalHunter.current.muted)};if(videos.isEmpty())HNotice("No hay publicaciones guardadas para este canal.")}
@Composable fun CreatorRefresh(ui:NativeUi){val s=ui.store;var status by remember{mutableStateOf("Consultando los canales…")};var done by remember{mutableStateOf(false)};LaunchedEffect(Unit){try{val data=withContext(Dispatchers.IO){CreatorFeedNative.refresh(s)};s.state.put("creatorData",data);s.save();val ok=data.a("channels").objects().count{it.s("status")=="ok"};status="${ok} de 5 canales actualizados. Se conservan las publicaciones anteriores cuando no hay conexión."}catch(e:Exception){status="No se pudo actualizar. Se conservan las publicaciones guardadas."}finally{done=true}};Heading("Publicaciones de entrenadores",size=32);HNotice(status);if(done)HButton("Continuar",primary=true){ui.back()}}
@Composable fun GoalEditor(ui:NativeUi,data:JSONObject){var title by remember{mutableStateOf(data.s("title",data.s("text")))};var repeat by remember{mutableStateOf(data.s("repeat","daily"))};Heading(if(data.s("id").isBlank())"Añadir objetivo" else "Editar objetivo",size=34);HInput(title,{title=it},"¿Qué quieres lograr?",multiline=true);Chips(listOf("daily" to "Cada día","once" to "Una vez"),repeat){repeat=it};HButton("Guardar objetivo",Modifier.fillMaxWidth(),primary=true){ui.attempt{require(title.isNotBlank());if(data.s("id").isBlank())ui.store.addGoal(title,repeat) else{data.put("title",title.take(200));data.put("text",title.take(200));data.put("repeat",repeat);ui.store.save()};ui.back()}}}
@Composable fun HistoryDetail(ui:NativeUi,date:String){val l=ui.store.logs.o(date);Eyebrow(date);Heading(kindLabel(l.s("kind")),size=34);HText("${if(l.b("complete"))"Completado" else if(l.b("pain"))"Detenido" else "Parcial"} · Esfuerzo ${l.i("rpe")}/10");for(x in l.a("items").objects())HPanel(padding=16){Heading(ui.store.catalog.byId[x.s("id")]?.name?:x.s("id"),size=26);for((i,a)in x.a("actual").objects().withIndex())if(a.b("done"))HText("✓ Serie ${i+1}: ${a.n("value")} · ${a.n("kg")} kg",size=16);if(x.b("missionState"))HText("Objetivo marcado",size=15,color=LocalHunter.current.muted)};HText(l.s("notes"));if(date==today()&&!l.b("complete")&&!l.b("pain"))HButton("Continuar registro"){ui.open("record",obj("date" to date))}}
