@Composable fun ReviewPanel(ui:NativeUi){val s=ui.store;val fb=s.planner.feedback(s.logs,today());Heading("Adaptación según tus registros",size=33);HText("${fb.completed} sesiones completadas · Esfuerzo medio ${"%.1f".format(fb.avg)} · Adherencia ${(fb.adherence*100).toInt()} %");HNotice(if(fb.strain)"Se registraron molestias, fatiga o esfuerzo alto. Revisa el volumen pendiente y tu perfil." else if(fb.canProgress)"Hay registros favorables para revisar una progresión compatible con tu nivel." else "Faltan sesiones completadas y datos de esfuerzo suficientes. Se mantiene el volumen.");HButton("Mantener próximas misiones",Modifier.fillMaxWidth(),primary=true){ui.attempt{s.review("mantener");ui.back()}};HButton("Reducir próximas misiones",Modifier.fillMaxWidth()){ui.attempt{s.review("reducir");ui.back()}};HButton("Pausar asignación automática",Modifier.fillMaxWidth()){ui.attempt{s.review("pausar");ui.back()}}}
fun coachAnswer(s:NativeStore,question:String):String{val q=normalize(question);val p=s.profile?:return "Completa tu perfil para revisar el plan.";val prefix=companionName(p)+": ";val ap=s.adjusted();val gate=s.rules.gate(ap);val fb=s.planner.feedback(s.logs,today())
 if(Regex("guardar perfil|actualizar perfil|cambiar objetivos|interpretacion del perfil").containsMatchIn(q))return prefix+"Tus objetivos, días, equipo, intensidad, modalidad, restricciones, apariencia y elección del acompañante se guardan juntos desde el botón «Guardar perfil». Los registros completados se mantienen."
 if(Regex("dolor|lesion|molestia|indicacion").containsMatchIn(q))return prefix+gate.reason+" Si aparece dolor, detén la sesión y actualiza tu perfil. No puedo diagnosticar ni indicar rehabilitación."
 if(Regex("progres|adaptacion|rendimiento|fatiga|esfuerzo|calendario|semana|descanso").containsMatchIn(q))return prefix+"La revisión semanal utiliza tus sesiones y esfuerzo registrados. "+when{fb.strain->"Se registró fatiga, molestias o esfuerzo alto; revisa y reduce las próximas misiones.";fb.canProgress->"Hay sesiones completadas y esfuerzo favorable para revisar una progresión compatible.";else->"Faltan registros comparables suficientes; se mantiene el volumen."}+" Los días manuales y con actividad se conservan."
 if(Regex("calent|cardio.*final").containsMatchIn(q))return prefix+"El calentamiento dura ${s.planner.phaseSeconds(ap)} segundos según tu nivel y la reducción elegida, con un máximo de 60 segundos. El cardio suave final usa la misma duración. Las series principales y sus descansos se conservan."
 if(Regex("animacion|velocidad|modelo|2d|3d|demostracion|video|visor").containsMatchIn(q))return prefix+"Esta versión utiliza ilustraciones 2D en las 1200 fichas y en la guía de cada sesión. La velocidad visual no modifica el reloj ni lo que registras. Consulta también las instrucciones de la ficha."
 if(Regex("gimnasio|maquina|polea|barra").containsMatchIn(q))return prefix+"Hay 122 sesiones de gimnasio en tres niveles. La selección usa tu equipo, objetivo, nivel y restricciones. Configura el equipo en Perfil y abre Rutinas especializadas en gimnasio."
 if(Regex("objetivo|meta|plan|perfil|quiero").containsMatchIn(q)){val intent=s.goals.interpret(p.s("finalGoal"),p.s("goalGroup","habit"));val plan=s.catalog.editorial.o("goalPlans").o(p.s("finalTarget",intent.s("target")));return prefix+"Tu objetivo es: ${plan.s("name")}. ${plan.s("why")} ${gate.reason} Revisa la familia y tu meta escrita desde Perfil."}
 if(Regex("entrenador|youtube|sergio|paufit|naty|metal|chuy").containsMatchIn(q))return prefix+"Los cinco entrenadores conservan sus apartados con enlaces a los canales y videos. Las 456 sesiones de biblioteca son diseños de Hunter System. Las publicaciones pendientes no se convierten en dosis."
 val terms=q.split(Regex("\\W+")).filter{it.length>3&&it !in listOf("como","hacer","hago","para","ejercicio","puedo","quiero")};val body=s.catalog.editorial.a("body").objects().map{it to terms.count{word->word in normalize(it.s("title")+" "+it.s("tags"))}}.filter{it.second>0}.sortedByDescending{it.second}.firstOrNull();if(body!=null&&Regex("anatom|fisioter|neuro|motric|equilibr|articul|flexion|supin|pronac").containsMatchIn(q))return body.first.s("title")+": "+body.first.s("body")
 val exercise=s.catalog.exercises.filter{it.raw.s("variant")=="base"}.map{it to terms.count{word->word in normalize(it.name)}}.filter{it.second>0}.maxByOrNull{it.second}?.first;if(exercise!=null){val reasons=s.rules.reasons(exercise,ap);return exercise.name+": "+exercise.raw.a("instructions").strings().joinToString(" ")+" "+exercise.raw.s("cue")+if(reasons.isEmpty())"" else " No está incluido para tu perfil: "+reasons.joinToString(", ")+"."}
 return "No encuentro esa pregunta en mis respuestas locales. Puedo explicar ejercicios del catálogo, tu plan, las restricciones y la evolución semanal. No tengo acceso a un modelo generativo ni a consultas en Internet."
}
@Composable fun CoachPanel(ui:NativeUi){
 val s=ui.store;val tier=LocalVisualTier.current
 val group=GroupEvolution.sessionGroup(s.day(today()),s.profile,s.catalog)?:""
 fun reply(question:String)=CompanionDialogue.message(s.profile,tier,DialogueContext(DialogueMoment.GUIDE,group=group))+
  "\n\n"+coachAnswer(s,question)
 CompanionStage(companionKey(s.profile),Modifier.fillMaxWidth().height(250.dp))
 Eyebrow("TU COMPAÑERO");Heading(companionName(s.profile),size=34);Heading("Guía personal",size=26)
 HText(CompanionDialogue.message(s.profile,tier,DialogueContext(DialogueMoment.WELCOME,group=group)),
  size=16,color=LocalHunter.current.muted)
 var question by remember{mutableStateOf("")};var answer by remember{mutableStateOf("")}
 HInput(question,{question=it.take(250)},"Pregunta sobre tu plan o un ejercicio",multiline=true)
 HButton("Preguntar",Modifier.fillMaxWidth(),primary=true){answer=reply(question)}
 for(q in listOf("¿Cómo se adapta mi plan?","¿Cuál es mi objetivo?","¿Qué pasa si siento dolor?"))
  HButton(q){question=q;answer=reply(q)}
 if(answer.isNotBlank())HPanel(padding=17){HText(answer)}
 HText("Respuestas locales basadas en datos y reglas del perfil; no utiliza IA remota.",size=14,color=LocalHunter.current.muted)
}
